mapper.select:
SELECT t1.id, t1.name, t1.money, t1.total, t1.last_total, t1.coupon_start_time, t1.coupon_end_time, t1.use_start_time, t1.use_end_time, t1.type, t1.cate_key, t1.min_money, t1.create_time, t1.update_time, t1.status, GROUP_CONCAT(t2.product_name) AS product_names, CASE WHEN NOW() >= t1.coupon_start_time THEN 0 ELSE CEILING(TIMESTAMPDIFF(SECOND, NOW(), t1.coupon_start_time) / 86400) END AS coupon_start_days, CASE WHEN NOW() < t1.coupon_start_time THEN 0 WHEN t1.coupon_end_time <= NOW() THEN 0 ELSE CEILING(TIMESTAMPDIFF(SECOND, NOW(), t1.coupon_end_time) / 86400) END AS coupon_end_days, CASE WHEN NOW() >= t1.use_start_time THEN 0 ELSE CEILING(TIMESTAMPDIFF(SECOND, NOW(), t1.use_start_time) / 86400) END AS use_start_days, CASE WHEN NOW() < t1.use_start_time THEN 0 WHEN t1.use_end_time <= NOW() THEN 0 ELSE CEILING(TIMESTAMPDIFF(SECOND, NOW(), t1.use_end_time) / 86400) END AS use_end_days, CONCAT(DATE_FORMAT(t1.use_start_time, '%Y-%m-%d %H:%i'), ' ~ ', DATE_FORMAT(t1.use_end_time, '%Y-%m-%d %H:%i')) AS consume_time_range, CONCAT(DATE_FORMAT(GREATEST(t1.coupon_start_time, t1.use_start_time), '%Y-%m-%d %H:%i'), ' ~ ', DATE_FORMAT(LEAST(t1.coupon_end_time, t1.use_end_time), '%Y-%m-%d %H:%i')) AS use_range_time FROM shop_product_coupon t1 LEFT JOIN shop_product t2 ON FIND_IN_SET(t2.id, t1.cate_key)
AND t1.name LIKE CONCAT('%', #{dto.name}, '%')
AND t1.type = #{dto.type}
AND t1.status = #{dto.status}
GROUP BY t1.id

SELECT 
FROM shop_product_coupon


        AND name LIKE CONCAT('%', #{dto.name}, '%')


        AND type = #{dto.type}


        AND status = #{dto.status}
